import{_ as l,a0 as i,w as m,s as a,ao as s,I as r,x as e,a1 as n,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse(`{"title":"Linux 的 ‘sort’命令的14個有用的範例（一） | LCTT x X-CMD","titleTemplate":false,"description":"Linux 的 ‘sort’命令的14個有用的範例（一） | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 的 ‘sort’命令的14個有用的範例（一） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 的 ‘sort’命令的14個有用的範例（一） | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150417 14 Useful Examples of Linux 'sort' Command--Part 1","title":"Linux 的 ‘sort’命令的14個有用的範例（一）","tag":"201505","desc":""},"relativePath":"201505/20150417 14 Useful Examples of Linux 'sort' Command--Part 1.md","filePath":"[post].md"}`),d={name:"201505/20150417 14 Useful Examples of Linux 'sort' Command--Part 1.md"};function u(c,t,w,x,f,g){const o=i("Link");return m(),a("div",null,[t[16]||(t[16]=s(`<h1 id="linux-的-sort-命令的14個有用的範例-一" tabindex="-1">Linux 的 ‘sort’命令的14個有用的範例（一） <a class="header-anchor" href="#linux-的-sort-命令的14個有用的範例-一" aria-label="Permalink to “Linux 的 ‘sort’命令的14個有用的範例（一）”">​</a></h1><p>Sort是用於對單個或多個文本文件內容進行排序的Linux程序。Sort命令以空格作為字段分隔符，將一行分割為多個關鍵字對文件進行排序。需要注意的是除非你將輸出重定向到文件中，否則Sort命令並不對文件內容進行實際的排序(即文件內容沒有修改)，只是將文件內容按有序輸出。</p><p>本文的目標是通過14個實際的範例讓你更深刻的理解如何在Linux中使用sort命令。</p><p>1、 首先我們將會創建一個用於執行‘sort’命令的文本文件（tecmint.txt）。工作路徑是‘/home/$USER/Desktop/tecmint’。</p><p>下面命令中的‘-e’選項將啓用‘\\’轉義，將‘\\n’解析成換行</p><pre><code>$ echo -e &quot;computer\\nmouse\\nLAPTOP\\ndata\\nRedHat\\nlaptop\\ndebian\\nlaptop&quot; &gt; tecmint.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Split-String-by-Lines.gif" alt="Split String by Lines in Linux"></p><p>2、 在開始學習‘sort’命令前，我們先看看文件的內容及其顯示方式。</p><pre><code>$ cat tecmint.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Check-Content-of-File.gif" alt="Check Content of File"></p><p>3、 現在，使用如下命令對文件內容進行排序。</p><pre><code>$ sort tecmint.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-Content.gif" alt="Sort Content of File linux"></p><p><strong>注意</strong>：上面的命令並不對文件內容進行實際的排序，僅僅是將其內容按有序方式輸出。</p>`,14)),r("p",null,[t[1]||(t[1]=e("4、 對文件‘tecmint.txt’文件內容排序，並將排序後的內容輸出到名為sorted.txt的文件中，然後使用",-1)),n(o,{href:"http://www.tecmint.com/13-basic-cat-command-examples-in-linux/"},{default:p(()=>[...t[0]||(t[0]=[e("cat",-1)])]),_:1}),t[2]||(t[2]=e("命令查看驗證sorted.txt文件的內容。",-1))]),t[17]||(t[17]=s(`<pre><code>$ sort tecmint.txt &gt; sorted.txt
$ cat sorted.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-File-Content.gif" alt="Sort File Content in Linux"></p><p>5、 現在使用‘-r’參數對‘tecmint.txt’文件內容進行逆序排序，並將輸出內容重定向到‘reversesorted.txt’文件中，並使用cat命令查看文件的內容。</p><pre><code>$ sort -r tecmint.txt &gt; reversesorted.txt
$ cat reversesorted.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-Content-By-Reverse.gif" alt="Sort Content By Reverse"></p><p>6、 創建一個新文件（lsl.txt），文件內容為在home目錄下執行‘ls -l’命令的輸出。</p><pre><code>$ ls -l /home/$USER &gt; /home/$USER/Desktop/tecmint/lsl.txt
$ cat lsl.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Populate-Output.gif" alt="Populate Output of Home Directory"></p><p>我們將會看到對其他字段進行排序的例子，而不是對默認的開始字符進行排序。</p><p>7、 基於第二列（符號連接的數量）對文件‘lsl.txt’進行排序。</p><pre><code>$ sort -nk2 lsl.txt
</code></pre><p><strong>注意</strong>：上面例子中的‘-n’參數表示對數值內容進行排序。當想基於文件中的數值列對文件進行排序時，必須要使用‘-n’參數。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-Content-by-Column.gif" alt="Sort Content by Column"></p><p>8、 基於第9列（文件和目錄的名稱，非數值）對文件‘lsl.txt’進行排序。</p><pre><code>$ sort -k9 lsl.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-Content-Based-on-Column.gif" alt="Sort Content Based on Column"></p><p>9、 sort命令並非僅能對文件進行排序，我們還可以通過管道將命令的輸出內容重定向到sort命令中。</p><pre><code>$ ls -l /home/$USER | sort -nk5
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-Content-By-Pipeline.gif" alt="Sort Content Using Pipe Option"></p><p>10、 對文件tecmint.txt進行排序，並刪除重複的行。然後檢查重複的行是否已經刪除了。</p><pre><code>$ cat tecmint.txt
$ sort -u tecmint.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-and-Remove-Duplicates.gif" alt="Sort and Remove Duplicates"></p><p>目前我們發現的排序規則：</p><p>除非指定了‘-r’參數，否則排序的優先級按下面規則排序</p><ul><li>以數字開頭的行優先級最高</li><li>以小寫字母開頭的行優先級次之</li><li>待排序內容按字典序進行排序</li><li>默認情況下，‘sort’命令將帶排序內容的每行關鍵字當作一個字符串進行字典序排序（數字優先級最高，參看規則 1）</li></ul><p>11、 在當前位置創建第三個文件‘lsla.txt’，其內容用‘ls -lA’命令的輸出內容填充。</p><pre><code>$ ls -lA /home/$USER &gt; /home/$USER/Desktop/tecmint/lsla.txt
$ cat lsla.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Populate-Output-With-Hidden-Files.gif" alt="Populate Output With Hidden Files"></p><p>瞭解ls命令的讀者都知道‘ls -lA’ 等於 ‘ls -l’ + 隱藏文件，所以這兩個文件的大部分內容都是相同的。</p><p>12、 對上面兩個文件內容進行排序輸出。</p><pre><code>$ sort lsl.txt lsla.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-Content-of-Multiple-Files.gif" alt="Sort Contents of Two Files"></p><p>注意文件和目錄的重複</p><p>13、 現在我們看看怎樣對兩個文件進行排序、合併，並且刪除重複行。</p><pre><code>$ sort -u lsl.txt lsla.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-Merge-Duplicates-Content.gif" alt="Sort, Merge and Remove Duplicates from File"></p><p>此時，我們注意到重複的行已經被刪除了，我們可以將輸出內容重定向到文件中。</p><p>14、 我們同樣可以基於多列對文件內容進行排序。基於第2,5（數值）和9（非數值）列對‘ls -l’命令的輸出進行排序。</p><pre><code>$ ls -l /home/$USER | sort -t &quot;,&quot; -nk2,5 -k9
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-Content-By-Field-Column.gif" alt="Sort Content By Field Column"></p><p>先到此為止了，在接下來的文章中我們將會學習到‘sort’命令更多的詳細例子。屆時敬請關注我們。保持分享精神。若喜歡本文，敬請將本文分享給你的朋友。</p><hr>`,42)),r("p",null,[t[4]||(t[4]=e("via: ",-1)),n(o,{href:"http://www.tecmint.com/sort-command-linux/"},{default:p(()=>[...t[3]||(t[3]=[e("http://www.tecmint.com/sort-command-linux/",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=e("作者：",-1)),n(o,{href:"http://www.tecmint.com/author/avishek/"},{default:p(()=>[...t[5]||(t[5]=[e("Avishek Kumar",-1)])]),_:1}),t[9]||(t[9]=e(" 譯者：",-1)),n(o,{href:"https://github.com/cvsher"},{default:p(()=>[...t[6]||(t[6]=[e("cvsher",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),n(o,{href:"https://github.com/wxy"},{default:p(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[13]||(t[13]=e("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原創翻譯，",-1)),n(o,{href:"http://linux.cn/"},{default:p(()=>[...t[12]||(t[12]=[e("Linux中國",-1)])]),_:1}),t[15]||(t[15]=e(" 榮譽推出",-1))])])}const $=l(d,[["render",u]]);export{T as __pageData,$ as default};
